// Bundled snapshot of the 5 seeded applications' documents
// (frontend/public/data/documents.json, generated by
// backend/scripts/export_documents_bundle.py). Display-only: the frontend uses
// it as a fallback when the backend `documents` collection is empty (e.g. an
// unseeded database). It is NOT a replacement for MongoDB — the pipeline, chat
// document tools, uploads and vector search still read the database directly.
//
// Mirrors the `seedDemoApps.js` static-data pattern: lazy-loaded module with
// id-based lookups.
"use client";

const SEED_APP_IDS = new Set([
  'APP-2026-00001',
  'APP-2026-00002',
  'APP-2026-00003',
  'APP-2026-00004',
  'APP-2026-00005',
]);

let cache = null;

async function load() {
  if (cache) return cache;
  try {
    const res = await fetch('/data/documents.json');
    cache = res.ok ? await res.json() : [];
  } catch {
    cache = [];
  }
  return cache;
}

export function isSeedAppId(id) {
  return !!id && SEED_APP_IDS.has(String(id));
}

export function isSeedDocId(docId) {
  return !!docId && String(docId).startsWith('seed-');
}

export async function getSeedDocuments(applicationId) {
  const all = await load();
  return all.filter((d) => d.application_id === applicationId);
}

export async function getSeedDocument(docId) {
  const all = await load();
  return all.find((d) => d._id === docId) || null;
}
